class LoggingRepository implements ProductRepository {
  constructor(private inner: ProductRepository) {}

  async get(id: string) {
    console.time(`product:${id}`);
    try {
      return await this.inner.get(id);
    } finally {
      console.timeEnd(`product:${id}`);
    }
  }
}

class CachedProducts implements ProductRepository {
  private cache = new Map<string, {
    value: Product;
    expires: number;
  }>();

  constructor(private real: ProductRepository) {}

  async get(id: string) {
    const hit = this.cache.get(id);
    if (hit && hit.expires > Date.now()) return hit.value;

    const value = await this.real.get(id);
    this.cache.set(id, {
      value,
      expires: Date.now() + 30_000
    });
    return value;
  }
}

