function memoizeOne<A, R>(
  fn: (arg: A) => R
) {
  let hasValue = false;
  let lastArg: A;
  let lastResult: R;

  return (arg: A) => {
    if (hasValue && Object.is(arg, lastArg)) {
      return lastResult;
    }
    hasValue = true;
    lastArg = arg;
    return (lastResult = fn(arg));
  };
}

