export class ApproveInvoice {
  private repository =
    inject(InvoiceRepository);

  private permission =
    inject(InvoicePermission);

  private telemetry =
    inject(Telemetry);

  async execute(invoiceId: string) {
    this.permission
      .assertCanApprove(invoiceId);

    const result =
      await this.repository
        .approve(invoiceId);

    this.telemetry.track(
      'invoice.approved',
      { invoiceId }
    );

    return result;
  }
}

